<script>
'use strict';
/* =====================================================================
   9 V battery with two series resistors — interactive nodal simulation
   ===================================================================== */

/* ---------- the sketch data, exactly as provided ---------- */
const SKETCH = {
  title: "9 V battery with two series resistors",
  referenceNet: { fixed: "gnd", drawn: "gnd" },
  fixed: {
    components: [
      { id:"B1", type:"battery", nodes:["vcc","gnd"], value:9,   label:"9V",    box:[0.238,0.445,0.162,0.133], confidence:0.95 },
      { id:"R1", type:"resistor",nodes:["vcc","n1"],  value:100, label:"100 Ω", box:[0.572,0.45,0.046,0.096],  confidence:0.95 },
      { id:"R2", type:"resistor",nodes:["n1","gnd"],  value:480, label:"480 Ω", box:[0.572,0.585,0.046,0.077], confidence:0.90 }
    ]
  },
  asDrawn: {
    components: [
      { id:"B1", type:"battery", nodes:["vcc","gnd"], value:9,   label:"9V",    box:[0.238,0.445,0.162,0.133], confidence:0.90 },
      { id:"R1", type:"resistor",nodes:["vcc","n1"],  value:100, label:"100 Ω", box:[0.572,0.45,0.046,0.096],  confidence:0.90 },
      { id:"R2", type:"resistor",nodes:["n1","gnd"],  value:480, label:"480 Ω", box:[0.572,0.585,0.046,0.077], confidence:0.80 }
    ]
  },
  mistakes: []
};

const BATTERY_R = 0.2;          // internal resistance, ohms
const LED_RATED = 0.020;        // 20 mA
const LED_BURN  = 0.030;        // 30 mA burns out
const clamp01 = v => Math.max(0, Math.min(1, v));

/* ---------- mutable simulation state ---------- */
let mode = 'fixed';                       // starts in "Fixed"
const values    = { B1: 9, R1: 100, R2: 480 };
const positions = {};                      // potentiometer wipers, if any
const switches  = {};                      // switch / button states, if any
let   selectedNet = null;
let   lastSolution = null;

const componentsFor = m => (m === 'fixed' ? SKETCH.fixed : SKETCH.asDrawn).components;
const referenceFor  = m => SKETCH.referenceNet[m] || 'gnd';

/* =====================================================================
   Nodal analysis (Gaussian elimination, nonlinear solve for LEDs)
   ===================================================================== */
function gaussSolve(A, b){
  const n = b.length;
  const M = A.map((row, i) => row.slice().concat([b[i]]));
  for (let col = 0; col < n; col++){
    let piv = col;
    for (let r = col + 1; r < n; r++) if (Math.abs(M[r][col]) > Math.abs(M[piv][col])) piv = r;
    if (Math.abs(M[piv][col]) < 1e-12) M[piv][col] = 1e-12;
    const tmp = M[col]; M[col] = M[piv]; M[piv] = tmp;
    for (let r = 0; r < n; r++){
      if (r === col) continue;
      const f = M[r][col] / M[col][col];
      for (let c = col; c <= n; c++) M[r][c] -= f * M[col][c];
    }
  }
  return M.map((row, i) => row[n] / row[i]);
}

function ledColourVf(c){
  const s = ((c.label || '') + ' ' + (c.colour || '') + ' ' + (c.id || '')).toLowerCase();
  if (s.includes('red'))    return 1.8;
  if (s.includes('orange')) return 1.9;
  if (s.includes('yellow')) return 2.0;
  if (s.includes('green'))  return 2.1;
  if (s.includes('blue'))   return 3.0;
  if (s.includes('white'))  return 3.0;
  return 2.0;                             // unknown colour -> 2 V
}

function solveCircuit(comps, ref){
  const nodeSet = new Set();
  comps.forEach(c => (c.nodes || []).forEach(n => { if (n !== ref) nodeSet.add(n); }));
  const nodes = [...nodeSet];
  const idx = {}; nodes.forEach((n, i) => idx[n] = i);
  const N = nodes.length;
  const val = c => (values[c.id] !== undefined ? values[c.id] : (c.value !== undefined ? c.value : defaultValue(c)));

  let volts = new Array(N).fill(0);
  for (let iter = 0; iter < 80; iter++){
    const G = Array.from({ length: N }, () => new Array(N).fill(0));
    const I = new Array(N).fill(0);
    const ii = n => (n === ref ? -1 : idx[n]);
    const stampG = (a, b, g) => {
      const ia = ii(a), ib = ii(b);
      if (ia >= 0) G[ia][ia] += g;
      if (ib >= 0) G[ib][ib] += g;
      if (ia >= 0 && ib >= 0){ G[ia][ib] -= g; G[ib][ia] -= g; }
    };
    const stampI = (a, b, i) => {          // inject i into a, out of b
      const ia = ii(a), ib = ii(b);
      if (ia >= 0) I[ia] += i;
      if (ib >= 0) I[ib] -= i;
    };
    const vAt = n => (n === ref ? 0 : volts[idx[n]]);

    for (const c of comps){
      const v = val(c);
      switch (c.type){
        case 'battery': {
          const E = v, g = 1 / BATTERY_R;
          stampG(c.nodes[0], c.nodes[1], g);
          stampI(c.nodes[0], c.nodes[1], E * g);
          break;
        }
        case 'resistor':
        case 'lamp': {
          stampG(c.nodes[0], c.nodes[1], 1 / Math.max(v, 1e-6));
          break;
        }
        case 'switch':
        case 'button': {
          if (switches[c.id]) stampG(c.nodes[0], c.nodes[1], 1 / 0.001);
          break;                            // open switch: open circuit
        }
        case 'potentiometer': {
          const R = Math.max(v, 1e-6);
          const p = clamp01(positions[c.id] !== undefined ? positions[c.id] : 0.5);
          stampG(c.nodes[0], c.nodes[2], 1 / Math.max(p * R, 0.01));
          stampG(c.nodes[2], c.nodes[1], 1 / Math.max((1 - p) * R, 0.01));
          break;
        }
        case 'capacitor': break;            // open circuit at DC
        case 'led':
        case 'diode': {
          const vf = c.type === 'diode' ? 0.7 : ledColourVf(c);
          const rd = c.type === 'diode' ? 0.5 : 10;
          const vd = vAt(c.nodes[0]) - vAt(c.nodes[1]);
          let g, i;
          if (vd > vf){ g = 1 / rd; i = (vd - vf) / rd; } else { g = 1e-9; i = 0; }
          stampG(c.nodes[0], c.nodes[1], g);
          stampI(c.nodes[0], c.nodes[1], i - g * vd);   // linearized source
          break;
        }
      }
    }
    const x = gaussSolve(G, I);
    let diff = 0;
    for (let k = 0; k < N; k++) diff = Math.max(diff, Math.abs(x[k] - volts[k]));
    volts = x;
    if (diff < 1e-10) break;
  }

  /* ---------- build results ---------- */
  const nodeVolts = { [ref]: 0 };
  nodes.forEach((n, i) => nodeVolts[n] = volts[i]);
  const vAt = n => (n === ref ? 0 : nodeVolts[n]);

  const parts = {};
  for (const c of comps){
    const v = val(c);
    const va = vAt(c.nodes[0]), vb = vAt(c.nodes[1]);
    const voltage = va - vb;
    let current = 0, brightness, on, burnt;
    switch (c.type){
      case 'battery': current = (v - voltage) / BATTERY_R; break;   // delivered out of +
      case 'resistor': current = voltage / Math.max(v, 1e-6); break;
      case 'lamp':
        current = voltage / Math.max(v, 1e-6);
        brightness = clamp01(Math.abs(current) / 0.2);
        break;
      case 'switch':
      case 'button':
        on = !!switches[c.id];
        current = on ? voltage / 0.001 : 0;
        break;
      case 'potentiometer': {
        const p = clamp01(positions[c.id] !== undefined ? positions[c.id] : 0.5);
        current = (va - vAt(c.nodes[2])) / Math.max(p * Math.max(v, 1e-6), 0.01);
        break;
      }
      case 'capacitor': current = 0; break;
      case 'led':
      case 'diode': {
        const vf = c.type === 'diode' ? 0.7 : ledColourVf(c);
        const rd = c.type === 'diode' ? 0.5 : 10;
        current = voltage > vf ? (voltage - vf) / rd : 0;
        if (c.type === 'led'){ brightness = clamp01(current / LED_RATED); burnt = current > LED_BURN; }
        break;
      }
    }
    const entry = { current, voltage };
    if (brightness !== undefined) entry.brightness = brightness;
    if (on !== undefined) entry.on = on;
    if (burnt !== undefined) entry.burnt = burnt;
    parts[c.id] = entry;
  }
  return { nodes: nodeVolts, parts };
}

function defaultValue(c){
  switch (c.type){
    case 'battery': return 9;
    case 'resistor': return 1000;
    case 'potentiometer': return 10000;
    case 'capacitor': return 0.0001;
    case 'lamp': return 20;
    default: return 0;
  }
}

/* =====================================================================
   SVG construction helpers (vertical zigzag resistors)
   ===================================================================== */
function zigzagV(x, y1, y2, amp, teeth){
  amp = amp || 12; teeth = teeth || 6;
  const lead = Math.min(10, (y2 - y1) * 0.16);
  const a = y1 + lead, b = y2 - lead;
  const step = (b - a) / teeth;
  let d = 'M ' + x + ' ' + y1 + ' L ' + x + ' ' + a.toFixed(2);
  for (let i = 0; i < teeth; i++){
    const off = (i % 2 === 0 ? amp : -amp);
    d += ' L ' + (x + off).toFixed(2) + ' ' + (a + step * (i + 0.5)).toFixed(2);
  }
  d += ' L ' + x + ' ' + b.toFixed(2) + ' L ' + x + ' ' + y2;
  return d;
}
document.getElementById('rpath-R1').setAttribute('d', zigzagV(440, 150, 240, 13, 6));
document.getElementById('rpath-R2').setAttribute('d', zigzagV(440, 262, 352, 13, 6));

/* current-dot loop: out of battery +, across top, down resistors, back home */
const LOOP = [[150,206],[150,80],[440,80],[440,420],[150,420],[150,294]];
const SEGS = []; let LOOP_LEN = 0;
for (let i = 0; i < LOOP.length; i++){
  const a = LOOP[i], b = LOOP[(i + 1) % LOOP.length];
  const len = Math.hypot(b[0]-a[0], b[1]-a[1]);
  SEGS.push({ a, b, len, start: LOOP_LEN });
  LOOP_LEN += len;
}
function loopPoint(d){
  d = ((d % LOOP_LEN) + LOOP_LEN) % LOOP_LEN;
  for (const s of SEGS){
    if (d <= s.start + s.len){
      const t = (d - s.start) / s.len;
      return [s.a[0] + (s.b[0]-s.a[0]) * t, s.a[1] + (s.b[1]-s.a[1]) * t];
    }
  }
  return SEGS[0].a;
}
const N_DOTS = 16;
const dotsGroup = document.getElementById('dots');
const dotEls = [];
for (let i = 0; i < N_DOTS; i++){
  const c = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
  c.setAttribute('r', '3.6');
  dotsGroup.appendChild(c);
  dotEls.push(c);
}
let dotOffset = 0, dotSpeed = 0, lastT = null;
function animateDots(t){
  if (lastT === null) lastT = t;
  const dt = Math.min(0.05, (t - lastT) / 1000); lastT = t;
  if (dotSpeed > 0.5){
    dotOffset = (dotOffset + dotSpeed * dt) % LOOP_LEN;
    dotsGroup.style.opacity = '1';
    for (let i = 0; i < N_DOTS; i++){
      const p = loopPoint(dotOffset + i * (LOOP_LEN / N_DOTS));
      dotEls[i].setAttribute('cx', p[0].toFixed(2));
      dotEls[i].setAttribute('cy', p[1].toFixed(2));
    }
  } else {
    dotsGroup.style.opacity = '0.12';
    for (let i = 0; i < N_DOTS; i++){
      const p = loopPoint(i * (LOOP_LEN / N_DOTS));
      dotEls[i].setAttribute('cx', p[0].toFixed(2));
      dotEls[i].setAttribute('cy', p[1].toFixed(2));
    }
  }
  requestAnimationFrame(animateDots);
}
requestAnimationFrame(animateDots);

/* =====================================================================
   Rendering
   ===================================================================== */
const $ = id => document.getElementById(id);
const fmtV = v => (v < 0 ? '−' : '') + Math.abs(v).toFixed(2) + ' V';
const fmtV3 = v => (v < 0 ? '−' : '') + Math.abs(v).toFixed(3) + ' V';
const fmtI = i => {
  const a = Math.abs(i);
  if (a >= 1)    return i.toFixed(2) + ' A';
  if (a >= 1e-3) return (i * 1e3).toFixed(1) + ' mA';
  if (a >= 1e-6) return (i * 1e6).toFixed(1) + ' µA';
  return '0.0 µA';
};
const fmtOhm = v => (v >= 1000 ? (v / 1000).toFixed(v % 1000 ? 2 : 0) + ' kΩ' : Math.round(v) + ' Ω');

function currentOf(parts, id){ return parts[id] ? parts[id].current : 0; }

function render(){
  const comps = componentsFor(mode);
  const ref = referenceFor(mode);
  const sol = solveCircuit(comps, ref);
  lastSolution = sol;

  /* part value labels */
  $('val-B1').textContent = (+values.B1).toFixed(1).replace(/\.0$/, '') + ' V';
  $('val-R1').textContent = fmtOhm(values.R1);
  $('val-R2').textContent = fmtOhm(values.R2);

  /* measurements table */
  const tbody = document.querySelector('#meas tbody');
  tbody.innerHTML = '';
  for (const c of comps){
    const p = sol.parts[c.id];
    const tr = document.createElement('tr');
    tr.innerHTML = '<td class="id">' + c.id + '</td><td>' + fmtI(p.current) +
                   '</td><td>' + fmtV(p.voltage) + '</td>';
    tr.addEventListener('mouseenter', () => { const g = $('part-' + c.id); if (g) g.classList.add('hot'); });
    tr.addEventListener('mouseleave', () => { const g = $('part-' + c.id); if (g) g.classList.remove('hot'); });
    tbody.appendChild(tr);
  }

  /* current dots: speed proportional to loop current (use battery current) */
  const iLoop = Math.abs(currentOf(sol.parts, 'B1'));
  dotSpeed = iLoop < 2e-4 ? 0 : Math.min(150, Math.max(8, iLoop * 3300));

  /* probe readout (live) */
  updateProbe(sol);

  /* net highlight */
  ['vcc','n1','gnd'].forEach(n => {
    const w = $('wire-' + n), nl = $('nl-' + n);
    if (w)  w.classList.toggle('selected', selectedNet === n);
    if (nl) nl.classList.toggle('selected', selectedNet === n);
  });
  $('n1-dot').classList.toggle('selected', selectedNet === 'n1');

  /* mode badge + toggle buttons */
  $('modeBadge').textContent = mode === 'fixed' ? 'Fixed' : 'As drawn';
  $('btnFixed').classList.toggle('active', mode === 'fixed');
  $('btnDrawn').classList.toggle('active', mode !== 'fixed');

  /* mistakes panel */
  const list = $('mistake-list');
  list.innerHTML = '';
  const mistakes = mode === 'drawn' ? (SKETCH.mistakes || []) : [];
  if (mistakes.length){
    $('mistake-note').style.display = 'none';
    for (const m of mistakes){
      const li = document.createElement('li');
      const what = typeof m === 'string' ? m : (m.text || m.message || 'Fault');
      const where = (typeof m === 'object' && (m.part || m.net)) ? (m.part || m.net) : '';
      li.innerHTML = '<span class="tag">' + (where ? where : 'Fault') + '</span><span>' + what + '</span>';
      list.appendChild(li);
    }
  } else {
    $('mistake-note').style.display = 'block';
    $('mistake-note').innerHTML = mode === 'drawn'
      ? '<b>None found.</b> The drawn sketch matches the corrected circuit.'
      : '<b>Nothing to fix.</b> This is the corrected circuit.';
  }

  /* burnt LEDs, if any exist in a netlist */
  for (const c of comps){
    if (c.type === 'led' && sol.parts[c.id] && sol.parts[c.id].burnt){
      const li = document.createElement('li');
      li.innerHTML = '<span class="tag">' + c.id + '</span><span>LED burnt out — current above 30 mA (rated 20 mA).</span>';
      list.appendChild(li);
      $('mistake-note').style.display = 'none';
    }
  }
}

function updateProbe(sol){
  const solNow = sol || lastSolution;
  if (!selectedNet){
    $('probeNet').textContent = 'Click a wire…';
    $('probeVolts').textContent = '—';
    return;
  }
  const v = solNow.nodes[selectedNet];
  $('probeNet').textContent = 'Net ' + selectedNet;
  $('probeVolts').textContent = (v === undefined ? '—' : fmtV3(v));
}

/* =====================================================================
   Interaction
   ===================================================================== */
const tooltip = $('tooltip');
function showTooltip(html, x, y){
  tooltip.innerHTML = html;
  tooltip.style.display = 'block';
  const pad = 14;
  const r = tooltip.getBoundingClientRect();
  let left = x + pad, top = y + pad;
  if (left + r.width > window.innerWidth - 8) left = x - r.width - pad;
  if (top + r.height > window.innerHeight - 8) top = y - r.height - pad;
  tooltip.style.left = left + 'px';
  tooltip.style.top = top + 'px';
}
function hideTooltip(){ tooltip.style.display = 'none'; }

function partTooltipHTML(id){
  const comps = componentsFor(mode);
  const c = comps.find(k => k.id === id);
  if (!c || !lastSolution) return '';
  const p = lastSolution.parts[id];
  const typeName = c.type.charAt(0).toUpperCase() + c.type.slice(1);
  let extra = '';
  if (c.type === 'battery') extra = '<br><span class="tt-dim">Delivering power out of the + terminal</span>';
  if (p.burnt) extra = '<br><span class="tt-dim">Burnt out — over 30 mA</span>';
  return '<span class="tt-id">' + id + ' · ' + typeName + '</span><br>' +
         'Current: ' + fmtI(p.current) + '<br>' +
         'Voltage: ' + fmtV(p.voltage) + extra;
}

document.querySelectorAll('.part').forEach(g => {
  const id = g.getAttribute('data-part');
  g.addEventListener('mousemove', e => { showTooltip(partTooltipHTML(id), e.clientX, e.clientY); });
  g.addEventListener('mouseenter', () => g.classList.add('hot'));
  g.addEventListener('mouseleave', () => { g.classList.remove('hot'); hideTooltip(); });
});

/* click a net to probe it */
document.querySelectorAll('.wire-hit, .node-dot').forEach(el => {
  el.addEventListener('click', () => {
    const net = el.getAttribute('data-net');
    selectedNet = (selectedNet === net) ? null : net;
    render();
  });
});

/* sliders */
function bindSlider(sliderId, valId, partId, fmt){
  const s = $(sliderId), out = $(valId);
  s.addEventListener('input', () => {
    values[partId] = +s.value;
    out.textContent = fmt(+s.value);
    render();
  });
}
bindSlider('s-B1', 'cv-B1', 'B1', v => v.toFixed(1) + ' V');
bindSlider('s-R1', 'cv-R1', 'R1', fmtOhm);
bindSlider('s-R2', 'cv-R2', 'R2', fmtOhm);

/* mode toggle */
$('btnFixed').addEventListener('click', () => window.__sim.setMode('fixed'));
$('btnDrawn').addEventListener('click', () => window.__sim.setMode('drawn'));

/* =====================================================================
   Public API
   ===================================================================== */
window.__sim = {
  setMode(next){
    if (next !== 'fixed' && next !== 'drawn') return;
    mode = next;
    render();
  },
  setSwitch(id, closed){
    switches[id] = !!closed;
    render();
  },
  setValue(id, value){
    const v = +value;
    if (!isFinite(v)) return;
    values[id] = v;
    const s = $('s-' + id);
    if (s){ s.value = String(v); s.dispatchEvent(new Event('input', { bubbles: false })); }
    else render();
  },
  setPosition(id, p){
    positions[id] = clamp01(+p || 0);
    render();
  },
  state(){
    const comps = componentsFor(mode);
    const ref = referenceFor(mode);
    const sol = lastSolution || solveCircuit(comps, ref);
    const parts = {};
    for (const c of comps){
      const p = sol.parts[c.id];
      const entry = { current: p.current, voltage: p.voltage };
      if (p.brightness !== undefined) entry.brightness = p.brightness;
      if (p.on !== undefined) entry.on = p.on;
      if (p.burnt !== undefined) entry.burnt = p.burnt;
      parts[c.id] = entry;
    }
    const nodes = {};
    for (const k of Object.keys(sol.nodes)) nodes[k] = sol.nodes[k];
    return { mode, nodes, parts };
  }
};

/* initial solve + paint */
render();
</script>
